import React, { useState, useEffect } from "react";
import axios from "axios";
import "./manageUserAccounts.css";
import AdminSidebar from "../components/AdminSideBar";
import Navbar from "../components/navbar";
import Footer from "../components/footer";

function ManageUserAccounts() {
  const [name, setName] = useState("");
  const [email, setEmail] = useState("");
  const [role, setRole] = useState("");
  const [registrationNumber, setRegistrationNumber] = useState("");
  const [password, setPassword] = useState("");

  const [students, setStudents] = useState([]);
  const [supervisors, setSupervisors] = useState([]);
  const [evaluators, setEvaluators] = useState([]);

  const [editingUserId, setEditingUserId] = useState(null);
  const [editingType, setEditingType] = useState("");

  useEffect(() => {
    fetchUsers();
  }, []);

  const fetchUsers = async () => {
    try {
      const studentRes = await axios.get("/api/student");
      const supervisorRes = await axios.get("/api/facultyadvisor");
      const evaluatorRes = await axios.get("/api/evaluator");

      setStudents(studentRes.data);
      setSupervisors(supervisorRes.data);
      setEvaluators(evaluatorRes.data);
    } catch (err) {
      console.error("Failed to fetch users", err);
    }
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    try {
      let userPayload = { username: name, email, role, password };
      let userRes;

      if (editingUserId) {
        userRes = await axios.put(`/api/user/${editingUserId}`, userPayload);
      } else {
        userRes = await axios.post("/api/user", userPayload);
      }

      const userId = userRes.data._id;

      if (role === "Student") {
        const studentPayload = {
          userId,
          studentName: name,
          regNo: registrationNumber,
          isGrouped: false,
        };
        if (editingUserId) {
          await axios.put(`/api/student/${editingUserId}`, studentPayload);
        } else {
          await axios.post("/api/student", studentPayload);
        }
      } else if (role === "Supervisor") {
        const supervisorPayload = { userId, Name: name };
        if (editingUserId) {
          await axios.put(`/api/facultyadvisor/${editingUserId}`, supervisorPayload);
        } else {
          await axios.post("/api/facultyadvisor", supervisorPayload);
        }
      } else if (role === "Evaluator") {
        const evaluatorPayload = { userId, name };
        if (editingUserId) {
          await axios.put(`/api/evaluator/${editingUserId}`, evaluatorPayload);
        } else {
          await axios.post("/api/evaluator", evaluatorPayload);
        }
      }

      await fetchUsers();
      resetForm();
    } catch (error) {
      console.error("Error saving user:", error);
    }
  };

  const handleEdit = (user, type) => {
    setEditingUserId(user.userId);
    setEditingType(type);
    setName(type === "student" ? user.studentName : user.Name || user.name);
    setEmail(user.email || "");
    setRole(type === "student" ? "Student" : type === "supervisor" ? "Supervisor" : "Evaluator");
    setRegistrationNumber(user.regNo || "");
    setPassword(""); // not shown
  };

  const handleDelete = async (userId, type) => {
    try {
      await axios.delete(`/api/user/${userId}`);
      await axios.delete(`/api/${type}/${userId}`);
      await fetchUsers();
      alert("User deleted successfully.");
    } catch (error) {
      console.error("Failed to delete user:", error);
    }
  };

  const handleResetPassword = async (userId) => {
    const newPassword = prompt("Enter new password:");
    if (newPassword) {
      try {
        await axios.put(`/api/user/reset-password/${userId}`, { password: newPassword });
        alert("Password reset successfully.");
      } catch (err) {
        console.error("Failed to reset password", err);
      }
    }
  };

  const resetForm = () => {
    setName("");
    setEmail("");
    setRole("");
    setRegistrationNumber("");
    setPassword("");
    setEditingUserId(null);
    setEditingType("");
  };

  return (
    <div className="manage-user-accounts">
      <Navbar />
      <div className="content-wrapper">
        <AdminSidebar />
        <div className="main-content">
          <h1>Manage User Accounts</h1>
          <p>Add or edit accounts for students, supervisors, and evaluators</p>

          <form onSubmit={handleSubmit} className="user-form">
            <label>Name</label>
            <input type="text" value={name} onChange={(e) => setName(e.target.value)} required />

            <label>Email</label>
            <input type="email" value={email} onChange={(e) => setEmail(e.target.value)} required />

            <label>Password</label>
            <input type="password" value={password} onChange={(e) => setPassword(e.target.value)} required={!editingUserId} />

            <label>Role</label>
            <select value={role} onChange={(e) => setRole(e.target.value)} required>
              <option value="">Select Role</option>
              <option value="Student">Student</option>
              <option value="Supervisor">Supervisor</option>
              <option value="Evaluator">Evaluator</option>
            </select>

            {role === "Student" && (
              <>
                <label>Registration Number</label>
                <input
                  type="text"
                  value={registrationNumber}
                  onChange={(e) => setRegistrationNumber(e.target.value)}
                  required
                />
              </>
            )}

            <button type="submit">{editingUserId ? "Update" : "Submit"}</button>
          </form>

          <hr />

          {/* Student Table */}
          {students.length > 0 && (
            <div>
              <h2>Students</h2>
              <table>
                <thead>
                  <tr>
                    <th>Name</th><th>Reg No</th><th>Actions</th>
                  </tr>
                </thead>
                <tbody>
                  {students.map((student) => (
                    <tr key={student.userId}>
                      <td>{student.studentName}</td>
                      <td>{student.regNo}</td>
                      <td>
                        <button onClick={() => handleEdit(student, "student")}>Edit</button>
                        <button onClick={() => handleResetPassword(student.userId)}>Reset Password</button>
                        <button onClick={() => handleDelete(student.userId, "student")}>Delete</button>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          )}

          {/* Supervisor Table */}
          {supervisors.length > 0 && (
            <div>
              <h2>Supervisors</h2>
              <table>
                <thead>
                  <tr><th>Name</th><th>Actions</th></tr>
                </thead>
                <tbody>
                  {supervisors.map((sup) => (
                    <tr key={sup.userId}>
                      <td>{sup.Name}</td>
                      <td>
                        <button onClick={() => handleEdit(sup, "supervisor")}>Edit</button>
                        <button onClick={() => handleResetPassword(sup.userId)}>Reset Password</button>
                        <button onClick={() => handleDelete(sup.userId, "facultyadvisor")}>Delete</button>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          )}

          {/* Evaluator Table */}
          {evaluators.length > 0 && (
            <div>
              <h2>Evaluators</h2>
              <table>
                <thead>
                  <tr><th>Name</th><th>Actions</th></tr>
                </thead>
                <tbody>
                  {evaluators.map((eva) => (
                    <tr key={eva.userId}>
                      <td>{eva.name}</td>
                      <td>
                        <button onClick={() => handleEdit(eva, "evaluator")}>Edit</button>
                        <button onClick={() => handleResetPassword(eva.userId)}>Reset Password</button>
                        <button onClick={() => handleDelete(eva.userId, "evaluator")}>Delete</button>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          )}
        </div>
      </div>
      <Footer />
    </div>
  );
}

export default ManageUserAccounts;
